// 应用启动序列: 主窗口的显示时机。
//
// 主窗口以 `visible: false` 创建, **显示时机在首帧绘制之后** —— 不是首次渲染之后, 也不是
// 语言服务 / 配音服务就绪之后 (它们慢起来不可控, 状态栏本来就显示进度)。

import { getCurrentWindow } from '@tauri-apps/api/window';

/** 等首帧真正绘制完成: 单个 rAF 回调可能在样式应用之前触发, 连续两帧才保证画出来了。 */
export function afterFirstPaint(): Promise<void> {
  return new Promise((resolve) => {
    requestAnimationFrame(() => requestAnimationFrame(() => resolve()));
  });
}

/**
 * 首帧绘制完成后显示主窗口。
 *
 * 这是**唯一**显示窗口的地方 —— 别处再调一次会让"启动无白屏"这条约束失效。
 */
export async function revealWindow(): Promise<void> {
  await afterFirstPaint();
  await getCurrentWindow().show();
}
